CREATE TRIGGER guard_credit_issue BEFORE UPDATE ON records WHEN NEW.kind='invoices' AND json_extract(NEW.data,'$.invoiceType')='creditNote' AND json_extract(NEW.data,'$.status')='issued' AND json_extract(OLD.data,'$.status')!='issued' BEGIN
 SELECT CASE WHEN COALESCE((SELECT SUM(json_extract(data,'$.total')) FROM records WHERE owner=NEW.owner AND kind='invoices' AND archived=0 AND id!=NEW.id AND json_extract(data,'$.invoiceType')='creditNote' AND json_extract(data,'$.status')='issued' AND json_extract(data,'$.originalId')=json_extract(NEW.data,'$.originalId')),0)+json_extract(NEW.data,'$.total')>COALESCE((SELECT json_extract(data,'$.total') FROM records WHERE id=json_extract(NEW.data,'$.originalId') AND owner=NEW.owner AND kind='invoices' AND json_extract(data,'$.status')='issued'),0) THEN RAISE(ABORT,'credit_exceeds_invoice') END;
END;
