CREATE TRIGGER guard_withholding_payment BEFORE UPDATE ON records WHEN NEW.kind='withholdings' AND json_extract(NEW.data,'$.status')='validated' AND json_extract(OLD.data,'$.status')='draft' AND json_extract(NEW.data,'$.operation')='add' BEGIN
 SELECT CASE WHEN COALESCE((SELECT SUM(json_extract(data,'$.total')) FROM records WHERE owner=NEW.owner AND kind='withholdings' AND archived=0 AND id!=NEW.id AND json_extract(data,'$.status')!='draft' AND json_extract(data,'$.operation')='add' AND json_extract(data,'$.paymentId')=json_extract(NEW.data,'$.paymentId') AND NOT EXISTS(SELECT 1 FROM records c WHERE c.owner=NEW.owner AND c.kind='withholdings' AND c.archived=0 AND json_extract(c.data,'$.direction')=json_extract(NEW.data,'$.direction') AND json_extract(c.data,'$.reference')=json_extract(records.data,'$.reference') AND json_extract(c.data,'$.status')!='draft' AND json_extract(c.data,'$.operation') IN ('modify','cancel'))),0)+json_extract(NEW.data,'$.total')>COALESCE((SELECT json_extract(data,'$.amount') FROM records WHERE id=json_extract(NEW.data,'$.paymentId') AND owner=NEW.owner AND kind='payments' AND json_extract(data,'$.status')='cleared'),0) THEN RAISE(ABORT,'retention_exceeds_payment') END;
END;
